 'set + drawnow limitrate  (animation)', {
  'Real-time update without re-creating graphics objects:'
  ''
  '    set(h.rng(k),''XData'',[ru(1) s(1,k)]/1e3, ...);'
  '    drawnow limitrate;'
  ''
  'Changing XData/YData/ZData of existing lines is far faster than calling'
  'plot3 every frame; "limitrate" caps the refresh and keeps buttons responsive.'}
 'Local functions in this file', {
  'satPositions(P,t)      -> 3 x N ECEF satellite positions.'
  'solvePosition(S,rho,x0)-> [x,G,iterations]; Gauss-Newton LS fix.'
  'computeDOP(G,Renu)     -> GDOP, PDOP, HDOP, VDOP.'
  'walker/userTruth       -> constellation and true user trajectory.'}
};
lb = uicontrol(tab3,'Style','listbox','Units','normalized', ...
    'Position',[0.01 0.02 0.25 0.96],'String',docs(:,1),'FontSize',11, ...
    'Callback',@onDocSelect);
edDoc = uicontrol(tab3,'Style','edit','Units','normalized','Max',2, ...
    'Enable','inactive','Position',[0.27 0.02 0.72 0.96],'BackgroundColor','w', ...
    'FontName','Courier New','FontSize',12,'HorizontalAlignment','left', ...
    'String',docs{1,2});
 
%% =====================================================================
%  SECTION 5 - VISUALIZATION SETUP (3-D scene, ENU plot, error plot)
%  =====================================================================
% ---- 3-D scene: Earth, satellites, trails, pseudorange lines ----------
hold(ax3d,'on'); grid(ax3d,'on'); view(ax3d,135,25);
[X,Y,Z] = sphere(36);
surf(ax3d,P.Re/1e3*X,P.Re/1e3*Y,P.Re/1e3*Z,'FaceColor',[.3 .5 .85], ...
     'FaceAlpha',.55,'EdgeColor',[.6 .7 .9],'EdgeAlpha',.35);
axis(ax3d,'equal'); lim = 3.2e4;
set(ax3d,'XLim',[-lim lim],'YLim',[-lim lim],'ZLim',[-lim lim]);
xlabel(ax3d,'X ECEF [km]'); ylabel(ax3d,'Y ECEF [km]'); zlabel(ax3d,'Z ECEF [km]');
rotate3d(ax3d,'on');
 
h.trail = gobjects(P.nSat,1);  h.rng = gobjects(P.nSat,1);
for k = 1:P.nSat
    h.trail(k) = plot3(ax3d,nan,nan,nan,'-','Color',[.75 .75 .75]);
    h.rng(k)   = plot3(ax3d,nan,nan,nan,'-','Color',[0 .65 .25],'LineWidth',1);
end
h.satVis = plot3(ax3d,nan,nan,nan,'o','MarkerFaceColor',[0 .65 .25], ...
